#[test]
fn the_six_originals_set_the_allocation_cap() {
    let _serial = lock(&SERIAL);
    if corpus().is_empty() {
        eprintln!("skip: no corpus drawing under test-file/; the cap stays at its floor");
        return;
    }
    let baseline = baseline();
    let mut failures = Vec::new();
    for measured in &baseline.originals {
        match &measured.outcome {
            Ok(Passed { parsed, largest }) => {
                println!(
                    "{}: largest single allocation {largest} B ({:.2} MiB), parsed {}, in {:.2?}",
                    measured.name,
                    mib(*largest),
                    if *parsed { "Ok" } else { "Err" },
                    measured.elapsed,
                );
                if !parsed {
                    failures.push(format!("{}: parse_reader said Err", measured.name));
                }
            }
            Err(failure) => {
                println!("{}: {failure}", measured.name);
                failures.push(format!("{}: {failure}", measured.name));
            }
        }
    }
    println!("allocation cap = {}", baseline.cap_text());
    assert!(
        failures.is_empty(),
        "the unmutated drawings must go through the chain cleanly:\n{}",
        failures.join("\n"),
    );
}

#[test]
fn every_case_is_built_the_same_twice() {
    let _serial = lock(&SERIAL);
    let corpus = corpus();
    let base = base_seed();
    let plan = default_plan(base, corpus);
    assert_eq!(
        plan.len(),
        1 + RANDOM_LENGTHS.len() + 1 + (DEFAULT_PICKS.len() + 1) * corpus.len(),
        "the default batch is empty 1 + random 9 + 15 per drawing",
    );
    assert_eq!(plan, default_plan(base, corpus), "default plan drifted");
    let extended = extended_plan(base, corpus);
    assert_eq!(
        extended.len(),
        1 + RANDOM_LENGTHS.len() + EXTENDED_RANDOM_DRAWS + EXTENDED_PER_FILE * corpus.len(),
    );
    assert_eq!(
        extended,
        extended_plan(base, corpus),
        "extended plan drifted"
    );
    let differ: Vec<String> = plan
        .iter()
        .filter(|case| {
            let source = case.source(corpus);
            build(source, &case.mutation, case.seed) != build(source, &case.mutation, case.seed)
        })
        .map(|case| case.line(corpus))
        .collect();
    assert!(
        differ.is_empty(),
        "built differently twice:\n{}",
        differ.join("\n"),
    );
}

/// The executor can go red: a planted panic and an allocation over the cap
/// both come back as failures. (A planted hang would cost 10 s and a leaked
/// thread, so the timeout path is left to `recv_timeout`.)
#[test]
fn the_executor_reports_a_planted_panic_and_overallocation() {
    fn panics(_: &[u8]) -> bool {
        panic!("planted panic")
    }
    fn allocates_two_mib(_: &[u8]) -> bool {
        black_box(vec![0u8; 2 << 20]);
        true
    }
    let _serial = lock(&SERIAL);
    match run_case("planted panic", Vec::new(), usize::MAX, panics) {
        Err(Failure::Panicked(text)) => assert!(
            text.contains("planted panic") && text.contains("arbitrary_bytes_never_panic.rs"),
            "the report lost the message or the location: {text}",
        ),
        other => panic!("a planted panic came back as {other:?}"),
    }
    match run_case("planted allocation", Vec::new(), 1 << 20, allocates_two_mib) {
        Err(Failure::OverAllocated { largest, cap }) => {
            assert!(
                largest >= 2 << 20 && cap == 1 << 20,
                "{largest} B, cap {cap} B"
            );
        }
        other => panic!("a 2 MiB allocation under a 1 MiB cap came back as {other:?}"),
    }
}

#[test]
fn the_default_batch_never_panics_hangs_or_overallocates() {
    let _serial = lock(&SERIAL);
    let corpus = corpus();
    let base = base_seed();
    let baseline = baseline();
    run_batch(
        "default",
        base,
        &default_plan(base, corpus),
        corpus,
        baseline,
    );
}

#[test]
#[ignore = "thousands of cases: cargo test --release --test arbitrary_bytes_never_panic -- --ignored"]
fn the_extended_batch_never_panics_hangs_or_overallocates() {
    let _serial = lock(&SERIAL);
    let corpus = corpus();
    let base = base_seed();
    let baseline = baseline();
    run_batch(
        "extended",
        base,
        &extended_plan(base, corpus),
        corpus,
        baseline,
    );
}
